  const canvas=ref.current;if(!canvas)return;
  const ctx=canvas.getContext('2d');if(!ctx)return;
  const motion=matchMedia('(prefers-reduced-motion: reduce)');
  // Handwritten captions in the reference hold a whole phrase, then cut.
  const groups=preset.id==='handwritten'
   ? preset.words.map((text,i)=>[{id:String(i),text,start:i*1.6,end:(i+1)*1.6}])
   : [preset.words.map((text,i)=>({id:String(i),text,start:i*.55,end:(i+1)*.55}))];
